SELECT lso."subject_title" , ( SELECT TO_NUMBER( regexp_replace( XMLQUERY( 'let $vals := tokenize($input, ",")
                           return if (count($vals) = 0) then ""
                           else if (count($vals) = 1) then $vals[1]
                           else (
                             let $result := xs:integer($vals[1])
                             for $i at $pos in $vals
                             where $pos > 1
                             return $result := bitwise-or($result, xs:integer($i))
                           ' PASSING LISTAGG( NVL( lso."num_enrolled_students" , 0 ) , ',' ) WITHIN GROUP( ORDER BY lso."num_enrolled_students" ) AS "input" RETURNING CONTENT ).getstringval( ) , '[^0-9]' , '' ) ) FROM dual ) AS "bit_or_result" FROM "library_reserve_matrl_detail" lrmd JOIN "library_subject_offered" lso ON lrmd."library_subject_offered_key" = lso."library_subject_offered_key" JOIN "library_material_status" lms ON lrmd."library_material_status_key" = lms."library_material_status_key" GROUP BY lso."subject_title"
